-- =====================================================================
-- Lib: stream helpers for videohost extractors: pickStream (generic
--      m3u8/mp4 scan) + hasMediaExt (mime typing of extension-less URLs).
-- Loaded via require_lib("hls"); uses require_lib("urls").
-- =====================================================================
local version = "1.0.0"

local urls = require_lib("urls")

local M = {}

-- =====================================================================
-- Generic stream scan
-- =====================================================================

function M.pickStream(t, embedUrl)
    -- 1) absolute URL
    local hls = t:match([=[(https?://[^"'%s\<>]+%.m3u8[^"'%s\<>]*)]=])
    if hls then return hls, "hls" end

    -- 2) quoted, relative or protocol-relative
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "([^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".m3u8", 1, true) then
                return urls.resolve(s, embedUrl), "hls"
            end
        end
    end

    -- 3) direct mp4
    local mp4 = t:match([=[(https?://[^"'%s\<>]+%.mp4[^"'%s\<>]*)]=])
    if mp4 then return mp4, "mp4" end
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "(//[^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".mp4", 1, true) then
                return urls.resolve(s, embedUrl), "mp4"
            end
        end
    end
    return nil, nil
end

-- =====================================================================
-- Media extension check
-- =====================================================================

-- Does the URL path (before "?" / "#") end with a media extension?
-- Without it media3 types the stream as progressive and fails on an HLS
-- body (rationale: ar/anime4up.lua:328). Union of the three plugin copies
-- (ar/anime4up.lua:330, ar/animephoenix.lua:45, ar/witanime.lua:1958):
-- .mkv comes from animephoenix and is progressive too, so it must not be
-- typed as "hls".
function M.hasMediaExt(u)
    local base = u:match("^[^%?#]*") or u
    return base:match("%.m3u8$") ~= nil
        or base:match("%.mp4$") ~= nil
        or base:match("%.mkv$") ~= nil
end

return M
end

__LOADERS["mailru"] = function(...)
-- =====================================================================
-- Lib: mail.ru — embed -> metadataUrl -> /+/video/meta/<id> -> mp4.
-- Merged from two copies: ar/anime4up.lua:907-946 and ar/witanime.lua:
-- 1438-1484 (both live 2026-10-05: the embed answers
-- "metadataUrl":"//my.mail.ru/+/video/meta/<id>", the meta JSON carries
-- videos[].url, the mp4 answers 206 on Range with the embed Referer; the
-- video_key cookie from meta is not required for playback).
-- Loaded via require_lib("mailru"). No dependencies on other libs.
--
-- The meta request is identical in both copies (same headers, same
-- timeout) and lives here; the embed page itself is fetched by the caller
-- (ar/anime4up gets it from its batch, ar/witanime requests it with the
-- my.mail.ru Referer).
-- =====================================================================
local version = "1.0.0"

local M = {}

-- meta JSON body -> list of { url, quality }, or nil + reason.
function M.parseMeta(metaBody, fallbackQuality)
    local data = json_parse(metaBody)
    local videos = type(data) == "table" and data.videos or nil
    if type(videos) ~= "table" then return nil, "no videos[] in meta" end
    local out = {}
    for _, v in ipairs(videos) do
        local u = type(v) == "table" and v.url or nil
        local key = type(v) == "table" and type(v.key) == "string" and v.key or nil
        if type(u) == "string" and u ~= "" then
            out[#out + 1] = {
                url     = u:gsub("^//", "https://"),
                quality = key and ("Mail.ru · " .. key) or fallbackQuality,
            }
        end
    end
    if #out == 0 then return nil, "no links in videos[]" end
    return out
end

-- Embed body + embed link -> list of { url, quality }, or nil + reason
-- ("no metadataUrl in embed" | "meta HTTP <code>" | a parse reason).
-- fallbackQuality is used for entries without a `key`.
function M.resolve(embedBody, embedLink, fallbackQuality)
    local meta = type(embedBody) == "string"
        and embedBody:match('metadataUrl":"([^"]+)') or nil
    if not meta then return nil, "no metadataUrl in embed" end
    local r = http_get((meta:gsub("^//", "https://")), {
        headers = {
            ["Referer"] = embedLink,
            ["X-Requested-With"] = "XMLHttpRequest",
        },
        timeout = 10000,
    })
    if not r.success then return nil, "meta HTTP " .. tostring(r.code) end
    return M.parseMeta(r.body, fallbackQuality)
end

return M
end

__LOADERS["meta"] = function(...)
-- =====================================================================
-- Lib: book metadata normalization (rating, update date, status,
--      genre list) shared by the novel extractors.
-- Loaded via require_lib("meta"). No dependencies on other libs.
--
-- Nothing here maps or invents values: an input the site did not really
-- send comes back as nil (plus a log line) so the app shows nothing
-- instead of a made-up number.
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- =====================================================================
-- Rating
-- =====================================================================

-- First number in a rating string -> number in the site's own scale
-- (the app rescales), nil when there is none or it is out of range.
-- Covers the formats used by the getBookRating copies: "4.6" (bare
-- number / data-rating attribute), "8/10", "Rating: 7.5/10", "Rating: 9",
-- "Rank: 3" and the comma decimal separator ("4,6" = 4.6).
function M.rating(str)
    if type(str) ~= "string" then return nil end
    local n = str:match("(%d+[%.,]%d+)") or str:match("(%d+)")
    if not n then
        logErr("meta.rating: no number in " .. str:sub(1, 60))
        return nil
    end
    local v = tonumber((n:gsub(",", ".")))
    if not v or v < 0 or v > 10 then
        logErr("meta.rating: out of 0..10 range: " .. str:sub(1, 60))
        return nil
    end
    return v
end

-- =====================================================================
-- Last update date
-- =====================================================================

-- Relative "N <unit> ago" — EN from the normalizeUpdateDate copies
-- (en/novelphoenix.lua:305, en/freewebnovel.lua, en/lightnovelpub.lua,
-- en/wuxiabox.lua, mtl/sonicmtl.lua), RU from ru/ifreedom.lua:120 and
-- ru/jaomix.lua (which matches the unit as a substring, so plurals and
-- the odd abbreviation keep working). Months/years are approximate
-- (30/365 days), as in those copies.
local REL_EN = {
    second = 1, seconds = 1,
    minute = 60, minutes = 60,
    hour = 3600, hours = 3600,
    day = 86400, days = 86400,
    week = 604800, weeks = 604800,
    month = 2592000, months = 2592000,
    year = 31536000, years = 31536000,
}

local REL_RU = {
    { "секунд", 1 }, { "сек", 1 }, { "минут", 60 }, { "мин", 60 },
    { "час", 3600 }, { "ч", 3600 }, { "дн", 86400 },
    { "недел", 604800 }, { "нед", 604800 },
    { "месяц", 2592000 }, { "мес", 2592000 },
    { "год", 31536000 }, { "лет", 31536000 }, { "г", 31536000 },
}

local function relativeDate(str)
    local n, unit = str:match("(%d+)%s+([%a]+)%s+ago")
    if n then
        local secs = REL_EN[unit]
        if not secs then return nil end
        return os.date("%Y-%m-%d", os.time() - tonumber(n) * secs)
    end
    local num, word = str:match("(%d+)%s*([^%d%s]+)%s+назад")
    if not num then return nil end
    for _, pair in ipairs(REL_RU) do
        if word:find(pair[1], 1, true) then
            return os.date("%Y-%m-%d", os.time() - tonumber(num) * pair[2])
        end
    end
    return nil
end

-- Any date-ish string -> "YYYY-MM-DD" or nil (guide:277). Recognized:
-- ISO 8601 anywhere in the string ("2026-08-18T23:00:15.751Z") and the
-- relative forms above ("Updated 3 days ago", "3 дня назад"). Anything
-- else (month names, DD.MM.YY, site-specific wording) is deliberately
-- not guessed — pass the site's own format from the plugin.
function M.normalizeDate(str)
    if type(str) ~= "string" or str == "" then return nil end
    local y, m, d = str:match("(%d%d%d%d)%-(%d%d)%-(%d%d)")
    if y then return y .. "-" .. m .. "-" .. d end
    local rel = relativeDate(str)
    if rel then return rel end
    logErr("meta.normalizeDate: unrecognized " .. str:sub(1, 60))
    return nil
end

-- =====================================================================
-- Status
-- =====================================================================

-- Status text is shown by the app as-is (guide:264) — no mapping, no
-- case folding by default: plugins return the site's own string. Pass
-- { lower = true } only when the plugin really wants a lowercase label
-- (en/novelfire.lua is the only copy that lowercases).
function M.status(str, opts)
    if type(str) ~= "string" then return nil end
    local s = trim((str:gsub("%s+", " ")))
    if s == "" then return nil end
    if opts and opts.lower then
        if type(string_lower) == "function" then
            s = string_lower(s)
        else
            s = s:lower()
        end
    end
    return s
end

-- =====================================================================
-- Genres
-- =====================================================================

-- Collects genre names out of the elements returned by html_select (or
-- plain strings) — the shared inner loop of the getBookGenres copies
-- (e.g. ar/mangalik.lua:125, ru/allhentai.lua:179): trim/clean the label,
-- drop empties, drop duplicates, keep the site order. The selector and
-- the data source stay in the plugin.
function M.collectGenres(anchors, opts)
    local out, seen = {}, {}
    if type(anchors) ~= "table" then return out end
    for _, el in ipairs(anchors) do
        local raw
        if type(el) == "string" then
            raw = el
        elseif type(el) == "table" then
            raw = el.text
        end
        if type(raw) == "string" and raw ~= "" then
            local name
            if opts and opts.clean and type(string_clean) == "function" then
                name = string_clean(raw)
            elseif type(string_trim) == "function" then
                name = string_trim(raw)
            else
                name = trim(raw)
            end
            if name ~= "" and not seen[name] then
                seen[name] = true
                out[#out + 1] = name
            end
        end
    end
    return out
end

return M
end

__LOADERS["okru"] = function(...)
-- =====================================================================
-- Lib: ok.ru resolver — data-options (entity-encoded) -> JSON ->
--      flashvars.metadata -> stream candidates.
-- Merged from five copies: ar/anime4up.lua:662, ar/animephoenix.lua:849,
-- ar/witanime.lua:1536, id/anichin.lua:471, id/animexin.lua:484.
-- Loaded via require_lib("okru"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

local OKRU_REFERER = "https://ok.ru/"

-- body — the ok.ru player page. The caller does the http_get (four of the
-- five copies receive the body from a batch; ar/witanime.lua:1536 fetches
-- the page itself and keeps doing that on its side).
-- Returns a list of { url, mime, name?, referer }; empty list when nothing
-- was parsed. Logging is plugin-specific and stays with the caller.
function M.resolveOkRu(body)
    if type(body) ~= "string" then return {} end
    -- Stub instead of the player: video removed or geo-blocked. Not a
    -- parser failure, so log it explicitly and bail out early.
    if body:find("vp_video_stub", 1, true) then
        log_error("ok.ru: video stub (removed or geo-blocked)")
        return {}
    end
    -- Primary: double quotes; fallback: single quotes.
    local opts = body:match('data%-options="([^"]+)"')
        or body:match("data%-options='([^']+)'")
    if not opts then
        log_error("ok.ru: no data-options, body len=" .. #body .. " head=" .. body:sub(1, 200))
        return {}
    end
    opts = opts:gsub("&quot;", '"'):gsub("&#39;", "'"):gsub("&lt;", "<")
        :gsub("&gt;", ">"):gsub("&amp;", "&")
    local ok, data = pcall(json_parse, opts)
    if not ok or type(data) ~= "table" or type(data.flashvars) ~= "table" then
        log_error("ok.ru: data-options parse failed, body len=" .. #body .. " opts=" .. opts:sub(1, 200))
        return {}
    end
    local meta = data.flashvars.metadata
    if type(meta) == "string" then
        local mok, m = pcall(json_parse, meta)
        meta = mok and type(m) == "table" and m or nil
    end
    if type(meta) ~= "table" then return {} end

    local out = {}
    -- The manifest URL carries no media extension: type it explicitly,
    -- otherwise media3 treats it as progressive (id/animexin.lua:482).
    if type(meta.hlsManifestUrl) == "string" and meta.hlsManifestUrl ~= "" then
        out[#out + 1] = {
            url = meta.hlsManifestUrl,
            mime = "hls",
            referer = OKRU_REFERER,
        }
    end
    -- videos[] are progressive renditions served without an extension.
    if type(meta.videos) == "table" then
        for _, v in ipairs(meta.videos) do
            local u = type(v) == "table" and v.url or nil
            if type(u) == "string" and u ~= "" then
                out[#out + 1] = {
                    url = u,
                    mime = "mp4",
                    name = type(v.name) == "string" and v.name or nil,
                    referer = OKRU_REFERER,
                }
            end
        end
    end
    return out
end

return M
end

__LOADERS["soraplay"] = function(...)
-- =====================================================================
-- Lib: soraplay — embed sources:[{"file":…,"label":…}] plus the
--      yonaplay/mirror go_to_player player list.
-- Extracted from ar/witanime.lua:1119-1161 (resolveSoraplay); only the
-- body parsing lives here — HTTP and the recursive host dispatch (the
-- go_to_player targets go back into the plugin's resolveHostedLink) stay
-- with the caller.
-- Loaded via require_lib("soraplay"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- yonaplay/mirror pages carry a player list (extractFromMulti in the
-- reference: .OD li → go_to_player → the host dispatcher again).
function M.isMulti(link)
    if type(link) ~= "string" then return false end
    local low = link:lower()
    return low:find("/mirror", 1, true) ~= nil or low:find("yonaplay", 1, true) ~= nil
end

-- go_to_player('…') targets; protocol-relative ones get the https: prefix.
function M.parsePlayers(body)
    local out = {}
    if type(body) ~= "string" then return out end
    for u in body:gmatch("go_to_player%('([^']*)'%)") do
        if u ~= "" then
            local target = u
            if not string_starts_with(target, "https:") then target = "https:" .. target end
            out[#out + 1] = target
        end
    end
    return out
end

-- Embed body -> list of { url, label }, possibly empty (the reference
-- cuts by `"file":"` / `"label":"`, quoted keys — unlike vidbom).
function M.parseSources(body)
    local out = {}
    if type(body) ~= "string" then return out end
    local p = body:find("sources: [", 1, true)
    local rest = p and body:sub(p + 10) or nil
    local data = rest and (rest:match("^(.-)%],") or rest) or nil
    if not data then return out end
    for src, label in data:gmatch('"file":"([^"]+)".-"label":"([^"]*)"') do
        out[#out + 1] = { url = src, label = label }
    end
    return out
end

return M
end

