-- =====================================================================
-- Lib: shared URL helpers (origin, unescapeSlashes, hostOf, resolve,
--      absUrl, driveDirectUrl) for videohost and novel extractors.
-- Loaded via require_lib("urls"). No dependencies on other libs.
-- =====================================================================
local version = "1.2.0"

local M = {}

-- =====================================================================
-- URL helpers
-- =====================================================================

function M.origin(url)
    local scheme, host = url:match("^(https?)://([^/?#]+)")
    if not scheme then return nil end
    return scheme .. "://" .. host .. "/"
end

function M.unescapeSlashes(s)
    local r = s:gsub("\\/", "/")
    r = r:gsub("\\u0026", "&")
    return r
end

function M.hostOf(url)
    return ((url or ""):match("^https?://([^/?#:]+)") or ""):lower()
end

-- Relative / protocol-relative URL -> absolute (relative to the embed).
function M.resolve(u, embedUrl)
    u = M.unescapeSlashes(u)
    if u:sub(1, 2) == "//" then return "https:" .. u end
    if u:find("^https?://") then return u end
    local o = M.origin(embedUrl or "")
    if o then
        o = o:gsub("/$", "")
        return o .. (u:sub(1, 1) == "/" and u or ("/" .. u))
    end
    return u
end

-- RFC 3986 merge, mirroring java.net.URI(base):resolve(href) — the exact
-- semantics of the engine global url_resolve (plugin-tester-jvm
-- LuaEngineCli.kt:355). Used only when that global is unavailable
-- (offline tests); in the app the global always wins.
local function removeDotSegments(p)
    local leading = p:sub(1, 1) == "/"
    local segs = {}
    for seg in p:gmatch("[^/]+") do
        if seg == ".." then
            if #segs > 0 and segs[#segs] ~= ".." then
                segs[#segs] = nil
            elseif not leading then
                segs[#segs + 1] = seg
            end
        elseif seg ~= "." then
            segs[#segs + 1] = seg
        end
    end
    local out = table.concat(segs, "/")
    if leading then out = "/" .. out end
    if p:sub(-1) == "/" and out:sub(-1) ~= "/" then out = out .. "/" end
    return out
end

local function splitRef(u)
    local path, query, fragment = u, "", ""
    local hash = path:find("#", 1, true)
    if hash then fragment = path:sub(hash + 1) path = path:sub(1, hash - 1) end
    local qm = path:find("?", 1, true)
    if qm then query = path:sub(qm + 1) path = path:sub(1, qm - 1) end
    return path, query, fragment
end

local function resolveRef(base, ref)
    if type(base) ~= "string" or type(ref) ~= "string" then return ref end
    if ref:match("^%a[%w+.-]*:") then return ref end
    local scheme, authority, rest = base:match("^(%a[%w+.-]*)://([^/?#]*)(.*)$")
    if not scheme then return ref end
    if ref:sub(1, 2) == "//" then return scheme .. "://" .. ref:sub(3) end
    local rPath, rQuery, rFrag = splitRef(ref)
    local bPath, bQuery = splitRef(rest)
    local path, query
    if rPath == "" then
        path = bPath
        query = (rQuery ~= "") and rQuery or bQuery
    elseif rPath:sub(1, 1) == "/" then
        path = rPath
        query = rQuery
    else
        path = (bPath:match("^.*/") or "/") .. rPath
        query = rQuery
    end
    local out = scheme .. "://" .. authority .. removeDotSegments(path)
    if query ~= "" then out = out .. "?" .. query end
    if rFrag ~= "" then out = out .. "#" .. rFrag end
    return out
end

-- href found in a page -> absolute URL, relative to `base` (usually baseUrl).
-- Union of the two inline variants: the dominant url_resolve one (guide:1763,
-- 36 byte-identical copies, e.g. ru/ranobehub.lua:11) and the manual sub/find
-- one (es/latanime.lua:94, en/hianimes.lua:50, id/anichin.lua:70). They agree
-- on absolute / protocol-relative / root-relative hrefs; for a bare relative
-- href the canonical url_resolve merge (RFC 3986) is used, the manual copies
-- joined it as baseDir .. "/" .. href — plugins relying on that join must be
-- checked during migration. Empty or non-string href -> "" (guide template).
function M.absUrl(base, href)
    if type(href) ~= "string" or href == "" then return "" end
    if href:sub(1, 4) == "http" then return href end
    if href:sub(1, 2) == "//" then return "https:" .. href end
    if type(url_resolve) == "function" then return url_resolve(base, href) end
    return resolveRef(base, href)
end

-- Google Drive file page -> direct usercontent download URL, no network:
-- the file id lives in the link itself (checked live 2026-10-03, usercontent
-- with confirm=t answers 206 without a single header).
-- Merged from the four inline copies: ar/anime4up.lua:813, ar/witanime.lua:1423,
-- ar/animephoenix.lua:698, es/latanime.lua:280 — all equivalent; the union keeps
-- the nil-safe host match (anime4up dereferenced match() without `or ""`).
-- ponytail: no playback-API fallback for "download disabled" (403 + UA binding) —
-- add it when locked links actually show up on the sites.
function M.driveDirectUrl(link)
    if type(link) ~= "string" then return nil end
    local host = (link:match("^https?://([^/]+)") or ""):lower()
    host = host:gsub("^www%.", "")
    if host ~= "drive.google.com" and host ~= "drive.usercontent.google.com" then
        return nil
    end
    local id = link:match("/file/d/([%w_-]+)") or link:match("[?&]id=([%w_-]+)")
    if not id then return nil end
    local u = "https://drive.usercontent.google.com/download?id=" .. id
        .. "&export=download&confirm=t"
    local rk = link:match("[?&]resourcekey=([%w_-]+)")
    if rk then u = u .. "&resourcekey=" .. rk end
    return u
end

return M
end

__LOADERS["vidbom"] = function(...)
-- =====================================================================
-- Lib: vidbom family (vidbom / vadbom / vedbam / myvid / segavid /
--      vidshare / vidsharer) — embed -> sources:[{file, label}].
-- Merged from two copies: ar/anime4up.lua:578-621 (VIDBOM_PATTERNS,
-- isVidbomLink, resolveVidbom) and ar/witanime.lua:1250-1274
-- (resolveVidbom + its own single-pattern host check).
-- Loaded via require_lib("vidbom"). No dependencies on other libs.
--
-- The body parsing is identical in both copies; the host check is the
-- union: ar/witanime matched only "//v[aie]d[bp][aoe]?m" (the literal
-- reference regex), ar/anime4up the four patterns covering the whole
-- family — the union routes every family domain to this parser.
-- HTTP stays with the caller (only ar/witanime fetches the embed).
-- =====================================================================
local version = "1.0.0"

local M = {}

-- VIDBOM_REGEX of Anime4Up.kt: alternation (|) does not exist in Lua
-- patterns, so instead of one regex there is a list; as in the reference
-- there is no "//" anchor — the host name matches anywhere in the URL
-- (subdomains included), but only after a dot.
local PATTERNS = {
    "v[aie]d[bp][aoe]?m%.",      -- vidbom / vadbom / vedbam
    "myvii?d%.",                 -- myvid / myviid
    "segavid%.",                 -- segavid
    "v[aei][aei]?dshar[er]?%.",  -- vidshare / vidsharer
}

function M.isLink(link)
    if type(link) ~= "string" then return false end
    local low = link:lower()
    for _, p in ipairs(PATTERNS) do
        if low:find(p) then return true end
    end
    return false
end

-- Embed body -> list of { url, quality }, possibly empty.
-- The reference reads script:containsData(sources) and cuts the body by
-- substringAfter("sources: [") + substringBefore("],").
function M.parseSources(body)
    if type(body) ~= "string" then return {} end
    local p = body:find("sources: [", 1, true)
    local rest = p and body:sub(p + 10) or nil
    local data = rest and (rest:match("^(.-)%],") or rest) or nil
    if not data then return {} end
    local out = {}
    for src, label in data:gmatch('file:"([^"]+)".-label:"([^"]*)"') do
        -- Reference: "Vidbom: " + label, longer than 15 chars -> "Vidshare: 480p".
        local quality = "Vidbom: " .. label
        if #quality > 15 then quality = "Vidshare: 480p" end
        out[#out + 1] = { url = src, quality = quality }
    end
    return out
end

return M
end

__LOADERS["videa"] = function(...)
-- =====================================================================
-- Lib: videa.hu (obfuscated _xt -> XML, often RC4 + base64 -> sources
--      with md5/expires).
-- Merged from two copies: ar/anime4up.lua:699-807 (videaToken, inline
-- random, resolveVidea) and ar/witanime.lua:1002-1129 (videaToken,
-- videaRandom8, resolveVidea). The token code was byte-identical; the
-- randomizer differs only in shape (inline table vs helper) and is
-- unified in random8().
-- Loaded via require_lib("videa"). No dependencies on other libs.
--
-- The HTTP stays with the caller (both copies build their own request:
-- different Referer source, different timeout), so the lib is split in
-- two pure steps: request() before the fetch, parse() after it.
-- =====================================================================
local version = "1.0.0"

local M = {}

local VIDEA_O = "xHb0ZvME5q8CBcoQi6AngerDu3FGO9fkUlwPmLVY_RTzj2hJIS4NasXWKy1td7p"
local VIDEA_R = { "e", "a", "g", "j", "d", "c", "h", "i", "b", "f" }
local VIDEA_RR = { "f", "h", "c", "b", "i" }

local function headerValue(headers, name)
    local v = headers and (headers[name] or headers[string.lower(name)])
    if type(v) == "table" then return v[1] end
    if type(v) == "string" then return v end
    return nil
end

-- _xt -> { t, k }: t goes into the XML request, k is the RC4 key of the
-- answer. Both halves must be assembled completely, otherwise the token
-- is wrong (returns nil).
local function token(xt)
    local c = {}
    for i = 1, #xt do
        local i0 = i - 1
        local k = VIDEA_R[math.floor(i0 / 8) + 2]
        if not k then return nil end
        if i0 % 8 == 0 then c[k] = "" end
        c[k] = (c[k] or "") .. xt:sub(i, i)
    end
    local d = (c.a or "") .. (c.g or "") .. (c.j or "") .. (c.d or "")
    local u = (c.c or "") .. (c.h or "") .. (c.i or "") .. (c.b or "")
    if d == "" or u == "" then return nil end
    local m = {}
    for i = 1, #d do
        local oi = VIDEA_O:find(d:sub(i, i), 1, true)
        if not oi then return nil end
        -- oi is 1-based while the reference formula is 0-based:
        -- i - (oi0 - 31) + 1
        local at = i - (oi - 32)
        if at < 1 or at > #u then return nil end
        m[i] = u:sub(at, at)
    end
    local mm = table.concat(m)
    c = {}
    for i = 1, #mm do
        local i0 = i - 1
        local k = VIDEA_RR[math.floor(i0 / 8) + 2]
        if k then
            if i0 % 8 == 0 then c[k] = "" end
            c[k] = (c[k] or "") .. mm:sub(i, i)
        end
    end
    c.f = ""
    return {
        t = (c.h or "") .. (c.c or ""),
        k = (c.b or "") .. (c.i or ""),
    }
end

-- The _s request parameter: 8 random [a-z0-9] chars, part of the RC4 key.
local function random8()
    local chars = "abcdefghijklmnopqrstuvwxyz0123456789"
    local out = {}
    for i = 1, 8 do
        local n = math.random(#chars)
        out[i] = chars:sub(n, n)
    end
    return table.concat(out)
end

M.random8 = random8

-- Embed page -> descriptor for the XML request, or nil + reason.
-- Descriptor: { url, key, rnd } — caller does http_get(url), then hands
-- the descriptor and the response to parse().
function M.request(link, body)
    if type(link) ~= "string" or type(body) ~= "string" then
        return nil, "no videa link"
    end
    local vcode = link:match("[?&]v=([%w]+)")
    if not vcode then return nil, "no v= in link" end
    local xt = body:match('_xt%s*=%s*"([^"]+)"') or body:match("_xt%s*=%s*'([^']+)'")
    if not xt then return nil, "no _xt in page" end
    local parts = token(xt)
    if not parts then return nil, "cannot parse _xt" end
    local rnd = random8()
    return {
        url = "https://videa.hu/player/xml"
            .. "?v=" .. url_encode(vcode)
            .. "&_t=" .. url_encode(parts.t)
            .. "&_s=" .. url_encode(rnd)
            .. "&platform=desktop&lang=en&start=0",
        key = parts.k,
        rnd = rnd,
    }
end

-- XML response -> list of { url, name }, or nil + reason.
-- The answer is either text/xml or RC4(key .. rnd .. x-videa-xs) over
-- base64 bytes; the server may also answer with an <error> element.
function M.parse(req, resp)
    if type(req) ~= "table" or type(resp) ~= "table" then
        return nil, "no videa response"
    end
    local contentType = headerValue(resp.headers, "content-type") or ""
    local xml
    if contentType:sub(1, 7) == "text/xml" then
        xml = resp.body
    else
        local xs = headerValue(resp.headers, "x-videa-xs") or ""
        xml = rc4(req.key .. req.rnd .. xs, base64_decode_bytes(resp.body) or "")
    end
    if type(xml) ~= "string" then return nil, "cannot decode XML" end

    local err = xml:match("<error[^>]*>([^<]*)</error>")
    if err then return nil, err end

    local exp = xml:match('<video_sources[^>]*exp="(%d+)"')
        or xml:match('<video_source[^>]*exp="(%d+)"')
    if not exp then return nil, "no exp in XML" end

    -- No backreference in Lua patterns, so the pattern stops right after
    -- `</hash_value_`. The two copies differed on the trailing `>` (only
    -- witanime's shape matches `</hash_value_1>`); dropping it keeps both
    -- possible closing-tag shapes working.
    local hashes = {}
    for name, h in xml:gmatch("<hash_value_([^>]+)>([^<]+)</hash_value_") do
        hashes[name] = h
    end

    local out = {}
    for name, path in xml:gmatch('<video_source name="([^"]+)"[^>]*>([^<]+)</video_source>') do
        local md5 = hashes[name]
        if md5 then
            out[#out + 1] = {
                url = "https:" .. path .. "?md5=" .. md5 .. "&expires=" .. exp,
                name = name,
            }
        end
    end
    if #out == 0 then return nil, "no sources in XML" end
    return out
end

return M
end

